export const modules:Module[] = categories.flatMap(category => raw[category.id].trim().split('\n').map((line,index) => {
  const [title,summary,rules,pitfall,example,demo,source,kind]=line.split('|');
  return {id:`${category.id}-${index+1}`,title,summary,rules:rules.split(';'),pitfall,example,demo:demo||category.demo,source:(source||category.source) as SourceKey,kind:(kind||category.kind) as Kind,category:category.id,index,tags:[category.short,demo,kind||category.kind]};
}));
export const getCategory=(id:string)=>categories.find(c=>c.id===id)!;
export const getModule=(id:string)=>modules.find(m=>m.id===id);
